import {EVALUATION_DATA,EVALUATION_ID,signature,makePlan,currentPlan,freeze,evaluate,latestEvidence} from '../chapter-09/model.mjs';
export {EVALUATION_DATA,EVALUATION_ID,signature,makePlan,currentPlan,freeze,evaluate,latestEvidence};
export const VERSION='1.0.0',STORAGE_KEY='qf-studio-chapter-10-v1';
export const STEPS=[['start','Choose your evidence route',20],['plan','Freeze a bounded question',20],['evidence','Calculate and retain',35],['memo','Draft a research memo',50],['review','Calibrate and self-review',25],['finish','Revise and export',30]];
export const CRITICAL=[['data','Synthetic provenance and dataset version identified; no claim of real-market profit.'],['timing','Signal at close; first eligible next open; no future data in positions.'],['benchmark','Strategy and buy-and-hold use the same eligible entry/exit dates and capital.'],['costs','Per-traded-notional entry, switch and final-exit costs; benchmark entry/exit too; cash 0, taxes/slippage excluded.'],['trials','Every run retained; base 10bps and sensitivity 30bps; no winning-case selection.'],['trace','Headline values trace to exported rows and correct hand calculation; conventions stated.'],['limits','At least three material limits; inspected evaluation labelled exploratory if plan changed.'],['claim','Conclusion is conditional; no guaranteed future return, deployability or personal recommendation.']];
export const RUBRIC=[{id:'dataScore',weight:20,title:'Data and reproducibility',anchors:'0: missing or false source. 10: synthetic source named but version or reproduction steps missing. 20: version, dates, inputs, row evidence and repeatable steps all traceable.'},{id:'calcScore',weight:25,title:'Calculations and conventions',anchors:'0: untraceable or materially wrong headline. 13: correct headline but missing hand check or units. 25: correct current run, full cost/return conventions and independently traceable hand check.'},{id:'designScore',weight:25,title:'Timing, benchmark, costs and evaluation design',anchors:'0: future data or mismatched dates unresolved. 13: chronology/costs mostly right but trial/reveal history unclear. 25: next-open execution, same-date net benchmark, frozen bounded plan, every trial and inspection caveat explicit.'},{id:'limitsScore',weight:20,title:'Interpretation and limitations',anchors:'0: guaranteed-profit or causal overclaim. 10: generic caveats with weak link to results. 20: evidence-based accept/reject/insufficient conclusion, both cost cases and at least three specific consequential limits.'},{id:'clarityScore',weight:10,title:'Clarity and response to feedback',anchors:'0: no revision. 5: readable draft with superficial correction. 10: concise 600–800-word memo, clear claims and a specific revision linked to criterion evidence.'}];
export const freshState=()=>({version:VERSION,fields:{},plans:[],runs:[],attempts:[],reviews:[],revisions:[],done:{}});
export const wordCount=s=>(s.trim().match(/\S+/g)||[]).length;
export function evidenceValid(s){const r=latestEvidence(s);return !!r&&String(s.fields.hand??'').trim()!==''&&Number.isFinite(Number(s.fields.hand))&&Math.abs(Number(s.fields.hand)-r.base.rows[0].endWealth)<.011;}
export function selfReview(s){const r=latestEvidence(s);if(!evidenceValid(s))throw Error('Run the current frozen plan and correct the first-row hand check before self-review.');const words=wordCount(s.fields.memo||'');if(words<600||words>800)throw Error('The assignment asks for a 600–800-word memo; length is a submission check, not a quality judgment.');if(!CRITICAL.every(([id])=>s.fields['critical-'+id]==='yes'))throw Error('Resolve every critical integrity criterion before self-review.');let score=0;for(const q of RUBRIC){const raw=s.fields[q.id];if(String(raw??'').trim()===''||!Number.isFinite(Number(raw))||Number(raw)<0||Number(raw)>q.weight)throw Error('Enter each rubric score within its range.');score+=Number(raw);}if((s.fields.reviewNote||'').trim().length<60)throw Error('Cite a specific weakness or verification and its evidence (60+ characters).');const review={time:new Date().toISOString(),memo:s.fields.memo,signature:r.signature,planVersion:r.planVersion,score,fields:{...s.fields},judgment:'Learner self-assessment, not independently validated'};s.reviews.push(review);return review;}
export function revisionValid(s){const r=latestEvidence(s),review=s.reviews.at(-1),revision=s.revisions.at(-1),words=wordCount(s.fields.memo||'');return !!r&&!!review&&!!revision&&review.signature===r.signature&&review.planVersion===r.planVersion&&review.score>=70&&review.memo!==s.fields.memo&&revision.reviewTime===review.time&&revision.signature===r.signature&&revision.memo===s.fields.memo&&revision.note===s.fields.revisionNote&&words>=600&&words<=800&&CRITICAL.every(([id])=>s.fields['critical-'+id]==='yes')&&RUBRIC.every(q=>s.fields[q.id]===review.fields[q.id])&&s.fields.reviewNote===review.fields.reviewNote&&evidenceValid(s);}
export function saveRevision(s){const r=latestEvidence(s),review=s.reviews.at(-1);if(!r||!review||review.signature!==r.signature||review.planVersion!==r.planVersion)throw Error('Self-review the current evidence first.');if(review.memo===s.fields.memo)throw Error('Change the memo after feedback; a revision note alone is not a revised memo.');if((s.fields.revisionNote||'').trim().length<60)throw Error('Explain the specific change, linked criterion and evidence (60+ characters).');s.revisions.push({time:new Date().toISOString(),reviewTime:review.time,signature:r.signature,memo:s.fields.memo,note:s.fields.revisionNote});if(!revisionValid(s))throw Error('Check word range, 70-point self-assessed rubric, critical criteria and current evidence. This does not validate prose quality.');}
export function completion(s){return {start:s.fields.setup==='yes',plan:!!currentPlan(s),evidence:evidenceValid(s),memo:wordCount(s.fields.memo||'')>=600&&wordCount(s.fields.memo||'')<=800,review:!!s.reviews.at(-1)&&s.reviews.at(-1).signature===latestEvidence(s)?.signature&&s.reviews.at(-1).planVersion===latestEvidence(s)?.planVersion&&(s.reviews.at(-1).memo===s.fields.memo||revisionValid(s)),finish:revisionValid(s)};}
export function restoreState(raw){try{const x=JSON.parse(raw);if(x.version!==VERSION||!x.fields||Object.values(x.fields).some(v=>typeof v!=='string')||!['plans','runs','attempts','reviews','revisions'].every(k=>Array.isArray(x[k])))throw Error();const s={...freshState(),...x};s.plans=s.plans.filter(p=>p?.plan&&p.signature===signature(p.plan)&&p.plan.window===3&&p.plan.costBps===10&&p.plan.initial===1000&&p.plan.segment===EVALUATION_ID);s.runs=s.runs.filter(r=>s.plans.some(p=>p.plan.version===r.planVersion&&p.signature===r.signature));/* Recompute rather than trust exported financial results. */const saved=s.runs;s.runs=[];for(const row of saved){const p=s.plans.find(p=>p.plan.version===row.planVersion);const tmp={fields:{question:p.plan.question,prediction:p.plan.prediction},plans:[p],runs:[]};const actual=evaluate(tmp);s.runs.push({...actual,time:row.time,exploratory:row.exploratory});}s.reviews=s.reviews.filter(r=>typeof r.memo==='string'&&r.fields&&typeof r.time==='string');s.revisions=s.revisions.filter(r=>typeof r.memo==='string'&&typeof r.note==='string');s.done=completion(s);return s;}catch{return freshState();}}
